public class Main {
    public static void main(String[] args) throws Exception {
        String s = new FastReader().next();  // empty input gives one empty entry, which is invalid
        String invalid = "[\"Invalid configuration\"]";
        String[] parts = s.split("\\|", -1);
        int n = parts.length;
        String[] out = new String[n];
        HashSet<String> values = new HashSet<>();
        for (String part : parts) {
            boolean ok = part.length() >= 5;
            for (int i = 0; ok && i < part.length(); i++) {
                char c = part.charAt(i);
                boolean digit = c >= '0' && c <= '9';
                ok = i < 4 ? digit : digit || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
            }
            if (!ok) { System.out.println(invalid); return; }
            int index = Integer.parseInt(part.substring(0, 4));
            String value = part.substring(4);
            if (index < 1 || index > n || out[index - 1] != null || !values.add(value)) {
                System.out.println(invalid);
                return;
            }
            out[index - 1] = value;
        }
        StringBuilder sb = new StringBuilder("[");
