import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func main() {
	parts := strings.Split(readToken(), "|") // empty input gives one empty entry, which is invalid
	const invalid = `["Invalid configuration"]`
	n := len(parts)
	out := make([]string, n)
	values := map[string]bool{}
	for _, part := range parts {
		ok := len(part) >= 5
		for i := 0; ok && i < len(part); i++ {
			c := part[i]
			digit := c >= '0' && c <= '9'
			ok = digit || (i >= 4 && (c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z'))
		}
		if !ok {
			fmt.Println(invalid)
			return
		}
		index, _ := strconv.Atoi(part[:4])
		value := part[4:]
		if index < 1 || index > n || out[index-1] != "" || values[value] {
			fmt.Println(invalid)
			return
		}
		out[index-1] = value
		values[value] = true
	}
	fmt.Println(`["` + strings.Join(out, `","`) + `"]`)
}

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readToken() string {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	var buf []byte
	for err == nil && b > ' ' {
		buf = append(buf, b)
		b, err = reader.ReadByte()
	}
	return string(buf)
}

func readInt() int {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	neg := false
	if b == '-' {
		neg = true
		b, err = reader.ReadByte()
	}
	r := 0
	for err == nil && b >= '0' && b <= '9' {
		r = r*10 + int(b-'0')
		b, err = reader.ReadByte()
	}
	if neg {
		return -r
	}
	return r
}
